static partial class Curriculum
{
    // Precalculus: every formula is tied to a physical or digital situation, every letter is
    // named as a variable or a constant with example values, and every step is explained in words.
    // docs/precalculus-curriculum.md has the authoring rules for this and future math courses.
    private static Exercise PrecalculusChoice(string title, string prompt, string correct, Choice[] choices, string hint, string test) =>
        new(ExerciseKind.MultipleChoice, title, prompt, ["Choose the best answer"], null, correct, choices, hint, [test]);

    private static Exercise PrecalculusNumeric(string title, string prompt, double expected, double tolerance, string unit, string hint, string workedSolution, IReadOnlyDictionary<string, double>? conversions = null) =>
        new(ExerciseKind.Numeric, title, prompt, ["Work it out step by step", "Enter the number and choose a unit"], null, null, [], hint, ["Uses the right model for the situation", "Keeps units consistent"], expected, tolerance, unit, conversions, workedSolution);

    private static Dictionary<string, double> PrecalculusUnits(params (string Unit, double Factor)[] units)
    {
        var map = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
        foreach (var (unit, factor) in units) map[unit] = factor;
        return map;
    }

